-- Feature build, snowflake dialect, visibility policy: point_in_time.
-- Generated by tools/emit_sql.py from the spec in features/spec.py.
-- Edit the spec, not this file; `make sql` regenerates and CI diffs.
-- Tables resolve in the session's default schema or dataset.
WITH visible AS (
    SELECT
        p.entity_id,
        p.prediction_time,
        p.prediction_days,
        e.event_id,
        e.event_type,
        e.fact_time,
        e.arrival_time,
        e.fact_days,
        e.value,
        e.status
    FROM predictions AS p
    JOIN events AS e
      ON e.entity_id = p.entity_id
     AND e.fact_time <= p.prediction_time AND e.arrival_time <= p.prediction_time
),
activity_window_30d AS (
    SELECT
        entity_id,
        COUNT(*) AS activity_count_30d,
        SUM(value) AS activity_amount_sum_30d
    FROM visible
    WHERE event_type = 'activity'
      AND fact_time > DATEADD(DAY, -30, prediction_time)
      AND fact_time <= prediction_time
    GROUP BY entity_id
),
incident_window_90d AS (
    SELECT
        entity_id,
        COUNT(*) AS incident_count_90d,
        MAX(value) AS incident_severity_max_90d
    FROM visible
    WHERE event_type = 'incident'
      AND fact_time > DATEADD(DAY, -90, prediction_time)
      AND fact_time <= prediction_time
    GROUP BY entity_id
),
last_activity AS (
    SELECT
        entity_id,
        prediction_days - MAX(fact_days) AS days_since_last_activity
    FROM visible
    WHERE event_type = 'activity'
    GROUP BY entity_id, prediction_days
),
latest_risk_assessment AS (
    SELECT entity_id, value AS last_risk_score
    FROM (
        SELECT
            entity_id,
            value,
            status,
            ROW_NUMBER() OVER (
                PARTITION BY entity_id
                ORDER BY fact_time DESC, arrival_time DESC, event_id DESC
            ) AS rn
        FROM visible
        WHERE event_type = 'risk_assessment'
    ) ranked
    WHERE rn = 1
),
latest_status_change AS (
    SELECT entity_id, CASE WHEN status = 'risky' THEN 1.0 ELSE 0.0 END AS status_risky
    FROM (
        SELECT
            entity_id,
            value,
            status,
            ROW_NUMBER() OVER (
                PARTITION BY entity_id
                ORDER BY fact_time DESC, arrival_time DESC, event_id DESC
            ) AS rn
        FROM visible
        WHERE event_type = 'status_change'
    ) ranked
    WHERE rn = 1
)
SELECT
    p.entity_id,
    COALESCE(activity_window_30d.activity_count_30d, 0) AS activity_count_30d,
    COALESCE(activity_window_30d.activity_amount_sum_30d, 0.0) AS activity_amount_sum_30d,
    last_activity.days_since_last_activity AS days_since_last_activity,
    latest_risk_assessment.last_risk_score AS last_risk_score,
    COALESCE(incident_window_90d.incident_count_90d, 0) AS incident_count_90d,
    incident_window_90d.incident_severity_max_90d AS incident_severity_max_90d,
    COALESCE(latest_status_change.status_risky, 0.0) AS status_risky
FROM predictions AS p
LEFT JOIN activity_window_30d
    ON activity_window_30d.entity_id = p.entity_id
LEFT JOIN last_activity
    ON last_activity.entity_id = p.entity_id
LEFT JOIN latest_risk_assessment
    ON latest_risk_assessment.entity_id = p.entity_id
LEFT JOIN incident_window_90d
    ON incident_window_90d.entity_id = p.entity_id
LEFT JOIN latest_status_change
    ON latest_status_change.entity_id = p.entity_id
ORDER BY p.entity_id
